    except AppInfoError as exc:
        raise AppInfoError(
            f"{old_contents / 'Info.plist'}: {exc}\nerror: {exc}"
        ) from exc

    if old_plist is not None and new_plist is not None:
        for key in DIFF_METADATA_KEYS:
